// 데이터 적을 경우 빈값 row삭제
scwin.btn_data2_onclick = function(e) {
	grd_depList.initGrid();
	for (var c = 12; c <= 19; c++) grd_depList.setColumnVisible(c,true);
	dlt_depList.setJSON(JSON.parse(JSON.stringify(scwin.fewData)));
	$.each(dlt_depList.getAllJSON(), function(i,v){
		if(v.byWayCount == 0) {
			for (var c = 12; c <= 19; c++) grd_depList.setCellVisible(i,c,false);
		} else if(v.byWayCount == 1) {
			for (var c = 16; c <= 19; c++) grd_depList.setCellVisible(i,c,false);
		}
	});
};

// 데이터 많을 경우
scwin.btn_data3_onclick = function(e) {
	grd_depList.initGrid();
	dlt_depList.setJSON(JSON.parse(JSON.stringify(scwin.manyData)));
};

// 데이터 많을 경우 빈값 row삭제
scwin.btn_data4_onclick = function(e) {
	grd_depList.initGrid();
	dlt_depList.setJSON(JSON.parse(JSON.stringify(scwin.manyData)));
	$.each(dlt_depList.getAllJSON(), function(i,v){
		if(v.byWayCount == 0) {
			for (var c = 12; c <= 19; c++) grd_depList.setCellVisible(i,c,false);
		} else if(v.byWayCount == 1) {
			for (var c = 16; c <= 19; c++) grd_depList.setCellVisible(i,c,false);
		}
	});
};

scwin.checkVal1 = function() {
	return (document.getElementById('grd_depList_scrollY_div') || document.getElementById('mf_grd_depList_scrollY_div')).style.width == '0px';
};
scwin.checkVal2 = function() {
	return (document.getElementById('grd_depList_body_tbody') || document.getElementById('mf_grd_depList_body_tbody')).children[0].style.display != 'none';
};
